class Payment(Base): __tablename__ = "payments"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); provider = Column(String(50), nullable=False); provider_payment_id = Column(String(255), nullable=True); provider_order_id = Column(String(255), nullable=True); amount_paise = Column(BigInteger, nullable=False); currency = Column(String(3), nullable=False, server_default="INR"); status = Column(Enum("INITIATED","SUCCESS","FAILED"), nullable=False, server_default="INITIATED"); plan_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("plans.id", ondelete="SET NULL", onupdate="CASCADE"), nullable=True); idempotency_key = Column(String(255), nullable=False); created_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); paid_at = Column(DateTime, nullable=True); activation_review_status = Column(Enum("PENDING","RESOLVED"), nullable=True); activation_review_reason = Column(String(255), nullable=True); activation_review_at = Column(DateTime, nullable=True); __table_args__ = (UniqueConstraint("provider","idempotency_key", name="uk_payments_idempotency"), UniqueConstraint("provider","provider_payment_id", name="uk_payments_payment_id"), UniqueConstraint("provider","provider_order_id", name="uk_payments_order_id"), Index("idx_payments_user_id", "user_id"), Index("idx_payments_status", "status"), Index("idx_payments_idempotency_key", "idempotency_key"))
