class PaymentRefund(Base):
    """Admin-initiated refund of a verified payment that could not be activated
    (manual review). One row per payment (UNIQUE payment_id): retries of a
    FAILED attempt reuse it; the gateway's refund id is UNIQUE. The original
    payment row is never modified except its activation_review_status."""
    __tablename__ = "payment_refunds"
    id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True)
    payment_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("payments.id", ondelete="RESTRICT", onupdate="CASCADE"), nullable=False)
    user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False)
    plan_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("plans.id", ondelete="SET NULL", onupdate="CASCADE"), nullable=True)
    intended_poster_type = Column(String(10), nullable=True)
    original_payment_status = Column(String(20), nullable=False)
    review_reason = Column(String(255), nullable=True)
    status = Column(Enum("REQUESTED","PENDING","PROCESSED","FAILED"), nullable=False, server_default="REQUESTED")
    amount_paise = Column(BigInteger, nullable=False)
    provider = Column(String(50), nullable=False)
    provider_refund_id = Column(String(255), nullable=True)
    gateway_status = Column(String(30), nullable=True)
    failure_code = Column(String(100), nullable=True)
    admin_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="RESTRICT", onupdate="CASCADE"), nullable=False)
    admin_reason = Column(String(500), nullable=False)
    attempts = Column(Integer, nullable=False, server_default="0")
    requested_at = Column(DateTime, nullable=False)
    processed_at = Column(DateTime, nullable=True)
    updated_at = Column(DateTime, nullable=True)
    __table_args__ = (
        UniqueConstraint("payment_id", name="uk_payment_refunds_payment"),
        UniqueConstraint("provider", "provider_refund_id", name="uk_payment_refunds_provider_refund"),
        Index("idx_payment_refunds_status", "status"),
    )
